<script setup lang="ts">
import {ref,watch,onUnmounted} from 'vue'
import {getTaskRecords,type TaskRecords} from '../services/admin.ts'
const props=defineProps<{id:number;updated:string}>()
const data=ref<TaskRecords|null>(null),status=ref('failed'),page=ref(1),busy=ref(false),error=ref('');let generation=0
const labels:Record<string,string>={pending:'待处理',succeeded:'成功',failed:'失败',skipped:'已过滤'}
async function load(){const v=++generation;busy.value=true;error.value='';try{const value=await getTaskRecords(props.id,page.value,status.value);if(v===generation)data.value=value}catch(e){if(v===generation)error.value=String(e)}finally{if(v===generation)busy.value=false}}
watch(()=>props.id,()=>{page.value=1;data.value=null;void load()},{immediate:true});watch(()=>props.updated,()=>void load());watch(status,()=>{page.value=1;void load()});onUnmounted(()=>generation++)
</script>
<template><section class="task-records" aria-label="逐条处理记录"><header><h3>逐条处理记录</h3><div><select v-model="status" class="form-input" aria-label="处理记录状态"><option value="failed">失败记录</option><option value="">全部记录</option><option value="pending">待处理</option><option value="succeeded">成功记录</option><option value="skipped">已过滤</option></select><button class="text-button" :disabled="busy" @click="load">刷新记录</button></div></header><p v-if="error" role="alert">{{error}}</p><p v-if="busy">正在读取处理记录…</p><template v-else-if="data"><p v-if="!data.total">该状态下没有处理记录。</p><article v-for="r in data.items" :key="r.id"><strong>{{r.source}} · {{r.source_id}}</strong><p>{{labels[r.status]??r.status}} · 阶段 {{r.stage}} · {{r.attempts==null?'历史记录':`已尝试 ${r.attempts} 次`}}</p><p v-if="r.error" class="record-error">{{r.error}}</p></article><div class="pages"><button class="text-button" :disabled="page<=1" @click="page--;load()">上一页记录</button><span>第 {{page}} / {{Math.max(1,Math.ceil(data.total/10))}} 页 · {{data.total}} 条</span><button class="text-button" :disabled="page*10>=data.total" @click="page++;load()">下一页记录</button></div></template></section></template>
<style scoped>.task-records{border-top:1px solid #e1eaea;padding:18px 0;font-size:12px}.task-records header,.task-records header>div,.pages{display:flex;gap:14px;align-items:center;flex-wrap:wrap}.task-records header{justify-content:space-between}.task-records article{border-bottom:1px solid #edf2f2;padding:12px 0;overflow-wrap:anywhere}.task-records p{line-height:1.8;color:#789099;margin:10px 0}.task-records .record-error{color:#a76f4b}.pages{margin-top:14px}</style>
